export interface ServicelistProps {
  /**
   * Variant
   * Friendly names map to internal IDs:
   *   "Desktop" → mpbuSloB4
   *   "Mobile" → ahKN7o5Se
   *   "Tablet" → Yz8m7SK5X
   */
  variant?: 'Desktop' | 'Mobile' | 'Tablet' | 'mpbuSloB4' | 'ahKN7o5Se' | 'Yz8m7SK5X';
  /**
   * Cursor 1 — pass as `lVTXes8OT` not `cursor1`.
   */
  lVTXes8OT?: string;
  /**
   * Cursor 2 — pass as `nM49zxtOZ` not `cursor2`.
   */
  nM49zxtOZ?: string;
  /**
   * Cursor 3 — pass as `wNMx0LJLM` not `cursor3`.
   */
  wNMx0LJLM?: string;
  /**
   * Cursor 4 — pass as `h2QFIa86Z` not `cursor4`.
   */
  h2QFIa86Z?: string;
  /**
   * Cursor — pass as `KwCT6qBIR` not `cursor`.
   */
  KwCT6qBIR?: string;
  /** Additional properties */
  [key: string]: unknown;
}
